#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk #:package MQTTnet@4.3.2.930 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable using System; using System.Text; using System.Threading.Tasks; using MQTTnet; using MQTTnet.Client; using MQTTnet.Server;  namespace MQTTNetDemo {     /// <summary>     /// MQTT演示程序 - 简化版     /// </summary>     public class Program     {         public static async Task Main(string[] args)         {             Console.WriteLine("MQTTnet Simple Demo");             Console.WriteLine("==================");              // 步骤1: 启动服务器             Console.WriteLine("\n1. Starting MQTT Server...");             var factory = new MqttFactory();             var server = factory.CreateMqttServer(new MqttServerOptions());             await server.StartAsync();             Console.WriteLine("✅ Server started on port 1883");              // 步骤2: 创建并连接客户端             Console.WriteLine("\n2. Creating MQTT Client...");             var client = factory.CreateMqttClient();                          Console.WriteLine("   Configuring client options...");             var clientOptions = new MqttClientOptions             {                 ChannelOptions = new MqttClientTcpOptions { Server = "127.0.0.1", Port = 1883 },                 ClientId = "SimpleClient",                 CleanSession = true             };              Console.WriteLine("   Connecting to server...");             await client.ConnectAsync(clientOptions);             Console.WriteLine("✅ Client connected");              // 步骤3: 订阅主题             Console.WriteLine("\n3. Subscribing to topic 'test/topic'...");             await client.SubscribeAsync("test/topic");             Console.WriteLine("✅ Subscribed to topic");              // 步骤4: 设置消息接收回调             Console.WriteLine("\n4. Setting up message handler...");             client.ApplicationMessageReceivedAsync += e =>             {                 var topic = e.ApplicationMessage.Topic;                 var payload = Encoding.UTF8.GetString(e.ApplicationMessage.PayloadSegment);                 Console.WriteLine($"📨 Received: Topic={topic}, Payload={payload}");                 return Task.CompletedTask;             };              // 步骤5: 发布消息             Console.WriteLine("\n5. Publishing message...");             var message = new MqttApplicationMessage             {                 Topic = "test/topic",                 PayloadSegment = new ArraySegment<byte>(Encoding.UTF8.GetBytes("Hello MQTT!"))             };             await client.PublishAsync(message);             Console.WriteLine("✅ Message published");              // 等待一下，确保消息被接收             await Task.Delay(1000);              // 步骤6: 清理资源             Console.WriteLine("\n6. Cleaning up resources...");             await client.DisconnectAsync();             await server.StopAsync();             Console.WriteLine("✅ Resources cleaned up");              Console.WriteLine("\nDemo completed successfully!");             Console.WriteLine("Press any key to exit...");             Console.ReadKey();         }     } }
